package com.sentinelai.incidents.api; import com.sentinelai.incidents.domain.IncidentTimeline; import com.sentinelai.incidents.infrastructure.*; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api/v1/incidents") public class IncidentTimelineController { private final IncidentRepository incidents; private final IncidentTimelineRepository timeline; public IncidentTimelineController(IncidentRepository i,IncidentTimelineRepository t){incidents=i;timeline=t;} @GetMapping("/{id}/timeline") public List<IncidentTimeline> get(@PathVariable UUID id,Authentication a){String t=tenant(a);if(incidents.findById(id).filter(i->t.equals(i.getTenantId())).isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return timeline.findByIncidentIdAndTenantIdOrderByCreatedAtAsc(id,t);} private String tenant(Authentication a){if(a instanceof JwtAuthenticationToken j){String t=j.getToken().getClaimAsString("tenant_id");if(t!=null&&!t.isBlank())return t;}throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant missing");} }
